def set_price (s : State) (model : String) (cents : Nat) : Except String (Nat × State) :=
  if model = "" then .error "model must not be empty"
  else .ok (cents, { s with prices := (model, cents) :: s.prices.filter (fun p => p.1 != model) })

def add_call (s : State) (key : String) (model : String) (tokens : Nat) : Except String (Nat × State) :=
  let s' : State := { s with calls := s.calls ++ [{ key := key, model := model, tokens := tokens }] }
  .ok (s'.used key, s')

def set_quota (s : State) (key : String) (q : Nat) : Except String (Nat × State) :=
  if h : s.used key > q then .error "quota is below the key's current usage"
  else .ok (q, { s with quotas := (key, q) :: s.quotas.filter (fun p => p.1 != key) })

